using System;
class ReplacementError : Exception {
    public ReplacementError() : base("replacement") { }
}
class ReplaceLeak {
    static int attempts;
    static async int Run() {
        try { return 17; }
        finally {
            await Task.Yield();
            attempts = attempts + 1;
            throw new ReplacementError();
        }
    }
    static async void Main() {
        try { await Run(); }
        catch (ReplacementError error) {
            Console.WriteLine(error.Message + ":" + Convert.ToString(attempts));
        }
    }
}
